mapper.select:
SELECT ci.*
FROM coupon_info ci
WHERE ci.deleted = 0

    AND ci.coupon_name LIKE CONCAT('%', #{reqVO.couponName}, '%')


    AND ci.coupon_type = #{reqVO.couponType}


    AND ci.status = #{reqVO.status}


    AND ci.scope = #{reqVO.scope}


    AND ci.create_time BETWEEN #{reqVO.createTime[0]} AND #{reqVO.createTime[1]}

ORDER BY ci.id DESC

SELECT id, coupon_name, coupon_type, COALESCE(threshold_amount, 0) as threshold_amount, COALESCE(discount_amount, 0) as discount_amount, scope, effective_type, effective_days, expiration_days, COALESCE(max_issue_count, 0) as max_issue_count, COALESCE(issued_count, 0) as issued_count, COALESCE(used_count, 0) as used_count FROM coupon_info
deleted = 0 AND status = 0
AND coupon_type = #{couponType}
AND author_id = #{authorId}
AND threshold_amount <= #{minAmount} AND discount_amount >= #{minAmount}
ORDER BY id DESC
